  // Pipe runs along ceiling
  beam(V(-2.7,2.50,.80),V(2.7,2.50,.80),.065,.065,0);
  beam(V(-2.7,2.35,.95),V(2.7,2.35,.95),.05,.05,1);

  // Warning lamps on top
  for(const x of [-2.8,2.8]){box(x,2.93,-1.01,.22,.36,.12,3);sphere(x,3.15,-1.01,.06,3)}
